// Одкровення — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Одкровення Ісуса Христа, яке дав Йому Бог, щоб показати рабам Своїм, що повинно статися невдовзі. І Він показав, пославши його через ангела Свого рабові Своєму Іоану,","який засвідчив слово Боже і свідчення Ісуса Христа і що він бачив.","Блажен, хто читає, і ті, що слухають слова пророцтва цього і дотримуються написаного в ньому, бо час близький.","Іоан семи церквам, що знаходяться в Асії: благодать вам і мир від Того, Хто є і був і гряде, та від семи духів, які знаходяться перед престолом Його,","і від Ісуса Христа, Який є свідок вірний, первісток з мертвих і владика царів земних. Йому, Який полюбив нас і омив нас від гріхів наших кров’ю Своєю","і зробив нас царями і священиками Богу й Отцю Своєму, слава і держава на віки віків, амінь.","Ось іде з хмарами, і побачить Його всяке око і ті, що прокололи Його; і заридають перед Ним усі племена земні. Так, амінь.","Я є Альфа й Омега, початок і кінець, говорить Господь, Який є і був і гряде, Вседержитель.","Я, Іоан, брат ваш і співучасник у скорботі і в царстві і в терпінні Ісуса Христа, був на острові, званому Патмос, за слово Боже і за свідчення Ісуса Христа.","Я був у дусі в день воскресний і чув позаду себе голос гучний, ніби трубний, який говорив: Я є Альфа й Омега, Перший і Останній;","те, що бачиш, напиши у книгу і пошли Церквам, які знаходяться в Асії: до Ефеса, і до Смирни, і до Пергама, і до Фіатири; і до Сардиса, і до Філадельфії, і до Лаодикії.","Я обернувся, щоб побачити, чий голос, що говорив зі мною; і, обернувшись, побачив сім золотих світильників","і, посеред семи світильників, подібного до Сина Людського, одягненого в довгі ризи і підперезаного попід груди золотим поясом:","голова Його і волосся білі, як біла вовна, як сніг; і очі Його, як полум’я вогняне;","і ноги Його подібні до бронзи, ніби в печі розжарені, і голос Його, як шум вод великих.","Він тримав у правиці Своїй сім зірок, і з уст Його виходив гострий з обох боків меч; і лице Його, як сонце, що сяє в силі своїй.","І коли я побачив Його, то впав до ніг Його, як мертвий. І Він поклав на мене правицю Свою і сказав мені: не бійся; Я є Перший і Останній,","і живий; і був мертвий, і ось, живий на віки віків, амінь; і маю ключі пекла і смерті.","Отже, напиши, що ти бачив, і що є, і що буде після цього.","Таємниця семи зірок, які ти бачив у правиці Моїй, і семи золотих світильників є така: сім зірок — це ангели семи Церков; а сім світильників, які ти бачив, це сім Церков."],"x":{"3":"52.11.28","4":"1.3.14|76.4.5","5":"25.88.38|56.1.19|58.1.7|63.15.20|68.1.18|75.9.14","6":"1.19.6|56.2.9","7":"31.3.14|48.12.10|50.24.30|61.1.14","8":"31.41.4|76.2.8","9":"62.8.17","10":"31.44.6|31.48.12","12":"1.25.37|48.4.2","13":"36.1.26|37.10.5:16|50.28.18","14":"37.7.9","15":"36.43.2|37.10.6","16":"31.49.2|50.28.18|66.6.17|76.2.16","17":"37.8.18","18":"24.12.14|31.22.22|76.3.7","20":"49.2.7"}},{"v":["Ангелові Ефеської Церкви напиши: так говорить Той, Хто тримає сім зірок у правиці Своїй, Хто ходить посеред семи золотих світильників:","знаю діла твої, і труд твій, і терпіння твоє, і те, що ти не можеш зносити розпутних, і випробував тих, які називають себе апостолами, а вони не такі, й побачив, що вони неправдомовці;","ти багато зазнав і маєш терпіння, і в ім’я Моє трудився і не знемагав.","Та маю проти тебе те, що ти залишив першу любов твою.","Отже, згадай, звідки ти впав, і покайся, і твори попередні діла; а якщо не так, скоро прийду до тебе і зрушу світильник твій з місця його, якщо не покаєшся.","А втім, те в тобі добре, що ти ненавидиш діла николаїтів, які і Я ненавиджу.","Хто має вухо, нехай чує, що Дух говорить Церквам: тому, хто перемагає, дам споживати від дерева життя, яке посеред раю Божого.","І ангелу Смирнської Церкви напиши: так говорить Перший і Останній, Який був мертвий і ось, живий:","знаю твої діла, і скорботу, і вбогість (а втім, ти багатий), і лихослів’я від тих, які кажуть про себе, що вони юдеї, а вони не такі, але зборище сатанинське.","Не бійся нічого, що тобі треба буде витерпіти. Ось, диявол буде кидати вас у темницю, щоб випробувати вас, і будете мати скорботу днів десять. Будь вірний до смерти, і дам тобі вінець життя.","Хто має вухо (чути), нехай чує, що Дух говорить Церквам: той, хто перемагає, не зазнає шкоди від другої смерти.","І ангелу Пергамської Церкви напиши: так говорить Той, Хто має гострий з обох боків меч:","знаю твої діла, і що ти живеш там, де престіл сатани, і що зберігаєш ім’я Моє, і не зрікся віри Моєї навіть у ті дні, коли у вас, де живе сатана, був убитий вірний свідок Мій Антипа.","Але маю трохи проти тебе, тому що є в тебе там ті, які дотримуються вчення Валаама, який навчив Валака спокусити синів Ізраїлевих, щоб вони їли ідоложертовне і перелюби чинили.","Так і в тебе є ті, які дотримуються вчення николаїтів, яке Я ненавиджу.","Покайся; а якщо не так, незабаром прийду до тебе і воюватиму з ними мечем уст Моїх.","Хто має вухо (чути), нехай чує, що Дух говорить Церквам: тому, хто перемагає, дам споживати сокровенну манну, і дам йому білий камінь, і на камені написане нове ім’я, якого ніхто не знає, крім того, хто одержує.","І ангелу Фіатирської Церкви напиши: так говорить Син Божий, у Якого очі, наче полум’я вогняне, і ноги подібні до бронзи:","знаю твої діла, і любов, і служіння, і віру, і терпіння твоє, і те, що останні діла твої більші, ніж перші.","Та маю трохи проти тебе, тому що ти попускаєш жінці Ієзавелі, яка називає себе пророчицею, навчати і вводити в оману рабів Моїх, любодіяти і їсти ідоложертовне.","Я дав їй час покаятись у перелюбстві її, але вона не покаялась.","Ось, Я кидаю її на одр і тих, що любодіяли з нею, у велику скорботу, якщо не покаються у ділах своїх.","І дітей її уражу смертю, і зрозуміють усі Церкви, що Я є Той, Хто випробовує серця й утроби; і воздам кожному з вас за ділами вашими.","Вам же та іншим, що є у Фіатирі, які не дотримуються цього вчення і не знають так званих глибин сатанинських, кажу, що не накладу на вас іншого тягара;","тільки те, що маєте, тримайте, доки прийду.","Хто перемагає і дотримується діл Моїх до кінця, тому дам владу над язичниками,","і буде пасти їх жезлом залізним; як посуд глиняний, вони будуть розтрощені, як і Я одержав владу від Отця Мого;","і дам йому зірку ранкову.","Хто має вухо (чути), нехай чує, що Дух говорить Церквам."],"x":{"1":"76.1.16","2":"58.4.1|64.11.13|72.2.19","3":"65.6.9","5":"36.18.24|76.3.3","7":"0.2.9|16.7.58","8":"31.41.4|31.44.6|31.48.12","9":"52.6.20|55.2.5|62.2.29","10":"50.10.21","11":"76.21.8","12":"76.1.16|76.19.21","14":"3.25.1|3.31.16","16":"31.11.4|70.2.8|76.1.16","17":"31.65.15|53.6.33","18":"76.1.14-15","19":"64.9.12","20":"1.34.15|63.10.19","23":"8.16.7|25.7.10|32.11.20|32.17.10","26":"37.7.22|53.6.29|63.6.3","27":"25.2.9","28":"57.1.19|76.22.16"}},{"v":["І ангелу Сардійської Церкви напиши: так говорить Той, Хто має сім духів Божих і сім зірок: знаю твої діла; ти носиш ім’я, ніби живий, але ти мертвий.","Пильнуй і зміцнюй інше близьке до смерти, бо Я не бачу, щоб діла твої були довершені перед Богом Моїм.","Згадай, що ти прийняв і чув, і зберігай та покайся. Якщо ж не будеш пильнувати, то Я найду на тебе, як злодій, і ти не дізнаєшся, якої години найду на тебе.","А втім, у тебе в Сардах є кілька чоловік, які не осквернили одягу свого, і будуть ходити зі Мною у білому одязі, бо вони достойні.","Той, хто перемагає, одягнеться у білий одяг; і не згладжу імені його з книги життя, і визнаю ім’я його перед Отцем Моїм і перед ангелами Його.","Хто має вухо, нехай чує, що Дух говорить Церквам.","І ангелу Філадельфійської Церкви напиши: так говорить Святий, Істинний, Хто має ключ Давидів, Хто відчиняє — і ніхто не зачинить, зачиняє — і ніхто не відчинить:","знаю твої діла; ось Я відчинив перед тобою двері, і ніхто не може зачинити їх; ти не багато маєш сили, і зберіг слово Моє, і не зрікся імені Мого.","Ось, Я зроблю, що із сатанинського зборища, з тих, які кажуть про себе, що вони юдеї, але не такі, а обманюють, — ось, Я зроблю те, що вони прийдуть і поклоняться перед ногами твоїми, і зрозуміють, що Я полюбив тебе.","І як ти зберіг слово терпіння Мого, то і Я збережу тебе від години спокуси, що гряде на весь світ, щоб випробувати тих, хто живе на землі.","Ось, гряду скоро; тримай, що маєш, щоб ніхто не перейняв вінця твого.","Переможця зроблю стовпом у храмі Бога Мого, і він уже не вийде геть; і напишу на ньому ім’я Бога Мого й ім’я міста Бога Мого, нового Єрусалима, що сходить з неба від Бога Мого, й ім’я Моє нове.","Хто має вухо, нехай чує, що Дух говорить Церквам.","І ангелові Лаодикійської Церкви напиши: так говорить Амінь, свідок вірний і істинний, початок створіння Божого:","знаю твої діла; ти ні холодний, ні гарячий; о, якби ти був холодний або гарячий!","Але оскільки ти теплий, а не гарячий і не холодний, то викину тебе з уст Моїх.","Бо ти говориш: я багатий, розбагатів і ні в чому не маю потреби; а не знаєш, що ти нещасний і жалюгідний, і вбогий, і сліпий, і голий.","Раджу тобі купити в Мене золото, вогнем очищене, щоб тобі збагатитися, і білий одяг, щоб одягтися, і щоб не видно було сорому наготи твоєї, і маззю для очей помаж очі твої, щоб бачити.","Кого Я люблю, тих викриваю і караю. Отже, будь ревним і покайся.","Ось, стою при дверях і стукаю; якщо хто почує голос Мій і відчинить двері, увійду до нього, і буду вечеряти з ним, і він зі Мною.","Переможцеві дам сісти зі Мною на престолі Моїм, як і Я переміг і сів з Отцем Моїм на престолі Його.","Хто має вухо, нехай чує, що Дух говорить Церквам."],"x":{"2":"36.33.7|50.24.42","3":"57.3.10|69.5.2|76.16.15","4":"76.6.11|76.7.9|76.19.8","5":"52.10.20|67.4.3","7":"24.12.14|31.22.22|52.1.32|76.1.18","8":"63.16.9|68.4.3","9":"31.49.23|31.60.14","10":"57.2.9|63.10.13","11":"76.2.10","12":"75.12.22|76.2.17|76.14.1","14":"68.1.15","17":"38.12.8|63.4.8","18":"76.7.13|76.16.15|76.19.8","19":"26.3.12|75.12.5","20":"28.5.2|53.14.23","21":"50.19.28|76.1.6|76.2.27"}},{"v":["Після цього я глянув, і ось, двері відчинені на небі, і той самий голос, який я чув, ніби звук труби, що говорив зі мною, сказав: зійди сюди, і покажу тобі, що має бути після цього.","І в ту ж мить я був у дусі; і ось, престіл стояв на небі, і на престолі був Сидячий;","і Цей Сидячий на вигляд був подібний до каменя яспису і сардису; і райдуга навколо престолу, на вигляд подібна до смарагду.","І навколо престолу двадцять чотири престоли; а на престолах бачив я двадцять чотири старці, які сиділи й одягнені були в білий одяг та мали на головах своїх золоті вінці.","І від престолу виходили блискавки, і громи, і голоси, і перед престолом горіли сім світильників вогняних, які є сім духів Божих;","і перед престолом море скляне, подібне до кристала, і посеред престолу і навколо престолу чотири тварини, сповнені очей спереду і ззаду.","І перша тварина була подібна до лева, і друга тварина подібна до тельця, і третя тварина мала лице, як людина, а четверта тварина подібна до орла, що летить.","І кожна з чотирьох тварин мала по шість крил навколо, а всередині вони були сповнені очей; і ні вдень, ні вночі не мають спокою, взиваючи: свят, свят, свят Господь Бог Вседержитель, Який був, є і гряде.","І коли тварини воздають славу і честь і подяку Тому, Хто сидить на престолі, Хто живе повік віку,","тоді двадцять чотири старці падають перед Тим, Хто сидить на престолі, і поклоняються Тому, Хто живе у віки віків, і покладають вінці свої перед престолом, кажучи:","достойний Ти, Господи, прийняти славу і честь і силу: бо Ти створив усе, і все з Твоєї волі існує і створено."],"x":{"2":"31.6.1|36.1.26|37.7.9","4":"76.1.6|76.2.26|76.1.3-4|76.6.11|76.7.13","5":"48.4.10|76.1.4|76.5.6|76.8.5","8":"31.6.2-3|76.1.8"}},{"v":["І бачив я у правиці Того, Хто сидить на престолі, книгу, написану всередині і ззовні, запечатану сімома печатями.","І бачив я ангела сильного, який виголошував гучним голосом: хто достойний розкрити цю книгу і зняти печаті її?","І ніхто не міг, ні на небі, ні на землі, ні під землею, ані розкрити цю книгу, ані глянути в неї.","І я багато плакав від того, що нікого не знайшлося достойного розкрити і читати цю книгу, і навіть глянути в неї.","І один із старців сказав мені: не плач; ось, лев від коліна Іуди, корінь Давидів, переміг, і може розкрити цю книгу і зняти сім печатей її.","І я поглянув, і ось, посеред престолу і чотирьох тварин і посеред старців стояв Агнець, ніби заколений, що мав сім рогів і сім очей, які є сім духів Божих, посланих на всю землю.","І Він прийшов і взяв книгу з правиці Того, Хто сидить на престолі.","І коли Він узяв книгу, тоді чотири тварини і двадцять чотири старці упали перед Агнцем, маючи кожен гуслі і золоті чаші, повні фіміаму, які є молитви святих.","І співають нову пісню, кажучи: достойний Ти взяти книгу і зняти з неї печаті, бо Ти був заколений, і кров’ю Своєю відкупив нас Богові з усякого коліна і народу, і людей, і племені,","і зробив нас царями і священиками Богові нашому; і ми будемо царювати на землі.","І я бачив, і чув голос багатьох ангелів навколо престолу, і тварин, і старців, і число їх було тьми тем і тисячі тисяч,","які говорили гучним голосом: достойний Агнець заколений прийняти силу і багатство, і премудрість, і міцність, і честь, і славу, і благословення.","І всяке створіння, яке є на небі і на землі, і під землею, і на морі, і все, що в них, чув я, говорило: Тому, Хто сидить на престолі, і Агнцеві благословення і честь, і слава і держава на віки віків.","І чотири тварини говорили: амінь. І двадцять чотири старці упали і поклонилися Тому, Хто живе у віки віків."],"x":{"1":"31.29.11","5":"0.49.9|31.11.1:10|62.15.12","6":"31.53.7|56.1.19","9":"54.20.28","10":"1.19.6|56.2.9","11":"37.7.10|75.12.22","13":"67.2.10|76.7.10"}},{"v":["І я бачив, що Агнець зняв першу із семи печатей, і я почув одну з чотирьох тварин, яка говорила ніби громовим голосом: іди і дивись.","Я глянув, і ось, кінь білий, і на ньому вершник, який мав лук, і дано було йому вінець, і вийшов він як переможний, і щоб перемогти.","І коли Він зняв другу печать, я чув другу тварину, яка говорила: іди і дивись.","І вийшов другий кінь, рудий, і тому, хто сидить на ньому, дано взяти мир від землі, і щоб убивали одне одного; і дано йому великий меч.","І коли Він зняв третю печать, я чув третю тварину, яка говорила: іди і дивись. Я глянув, і ось, кінь вороний, і на ньому вершник, який мав мірило у руці своїй.","І чув я голос посеред чотирьох тварин, який говорив: мірка пшениці за динарій*, і три мірки ячменю за динарій; єлею ж і вина не пошкоджуй.","І коли Він зняв четверту печать, я чув голос четвертої тварини, що говорив: іди і дивись.","І я глянув, і ось, кінь блідий, і на ньому вершник, якому ім’я «смерть»; і пекло слідом ішло за ним; і дана йому влада над четвертою частиною землі — умертвлювати мечем і голодом, і моровицею, і звірами земними.","І коли Він зняв п’яту печать, я побачив під жертовником душі убитих за слово Боже і за свідчення, яке вони мали.","І викликнули вони гучним голосом, кажучи: доки, Владико Святий і Істинний, не судиш і не мстишся тим, що живуть на землі, за кров нашу?","І дано було кожному з них одяг білий, і сказано їм, щоб вони заспокоїлися ще на деякий час, доки і співробітники їхні, і брати їхні, які будуть убиті, як і вони, доповнять число.","І коли Він зняв шосту печать, я глянув, і ось, стався великий землетрус, і сонце стало темне, як волосяниця, і місяць став, наче кров.","І зірки небесні попадали на землю, як смоковниця, струшувана сильним вітром, обсипає незрілі смокви свої.","І небо зникло, згорнувшись, як сувій; і всяка гора й острів зрушилися з місць своїх.","І царі земні, і вельможі, і багаті, і тисячоначальники, і сильні, і всякий раб, і всякий вільний сховались у печери і в ущелини гір,","і кажуть горам і каменям: упадіть на нас і закрийте нас від лиця Того, Хто сидить на престолі, й від гніву Агнця;","бо прийшов великий день гніву Його, і хто може встояти?"],"x":{"2":"76.19.11","5":"76.5.9","8":"36.14.21","10":"52.18.7|76.19.2","11":"76.3.5|76.7.9","12":"50.24.29","14":"31.34.4|75.1.11-12","16":"31.2.19|38.10.8|52.23.30|76.9.6"},"n":{"6":["Динарій — монета, відповідна денній платі поденникові."]}},{"v":["І після цього бачив я чотирьох ангелів, які стоять на чотирьох кутах землі, тримаючи чотири вітри землі, щоб не дув вітер ні на землю, ні на море, ні на яке дерево.","І бачив я іншого ангела, який сходив від сходу сонця, і мав печать Бога Живого. І викликнув він гучним голосом до чотирьох ангелів, яким дано шкодити землі і морю, кажучи:","не робіть шкоди ні землі, ні морю, ні деревам, доки не покладемо печаті на чолах рабів Бога нашого.","І я чув кількість пропечатаних: пропечатаних було сто сорок чотири тисячі від усіх колін синів Ізраїлевих.","З коліна Іудиного пропечатано дванадцять тисяч; з коліна Рувимового пропечатано дванадцять тисяч; з коліна Гадового пропечатано дванадцять тисяч;","з коліна Асирового пропечатано дванадцять тисяч; з коліна Неффалимового пропечатано дванадцять тисяч; з коліна Манасіїного пропечатано дванадцять тисяч;","з коліна Симеонового пропечатано дванадцять тисяч; з коліна Левіїнового пропечатано дванадцять тисяч; з коліна Іссахарового пропечатано дванадцять тисяч;","з коліна Завулонового пропечатано дванадцять тисяч; з коліна Йосифового пропечатано дванадцять тисяч; з коліна Веніамінового пропечатано дванадцять тисяч.","Після цього глянув я, і ось, велика кількість людей, яких ніхто не міг перелічити, з усіх племен і колін, і народів і людей, стояли перед престолом і перед Агнцем у білому одязі і з пальмовими віттями в руках своїх.","І викликували гучним голосом, кажучи: спасіння Богові нашому, що сидить на престолі, і Агнцеві!","І всі ангели стояли навколо престолу і старців, і чотирьох тварин і впали перед престолом на лиця свої, і поклонилися Богові,","кажучи: амінь! благословення і слава, і премудрість, і подяка, і честь, і сила, і кріпкість Богові нашому на віки віків! Амінь.","І, почавши говорити, один із старців запитав мене: хто ці, одягнені у білий одяг, і звідки прийшли?","Я сказав йому: ти знаєш, господарю. І він сказав мені: це ті, які прийшли від великої скорботи; вони омили одяг свій і вибілили одяг свій кров’ю Агнця.","За це вони перебувають нині перед престолом Бога і служать Йому день і ніч у храмі Його, і Той, Хто сидить на престолі, буде жити в них.","Вони вже не будуть мати ні голоду, ні спраги, і не буде палити їх сонце і ніяка спека:","бо Агнець, Який посеред престолу, буде пасти їх і водити їх до живих джерел вод; і витре Бог усяку сльозу з очей їхніх."],"x":{"3":"36.9.4|76.14.1","9":"76.3.5|76.6.11","10":"32.3.23|38.13.4|76.19.1","14":"31.1.18|75.9.14","15":"31.4.2|76.21.3","16":"25.120.6|31.49.10","17":"25.22.1|25.35.8-10|31.25.8|76.21.4"}},{"v":["І коли Він зняв сьому печать, настала безмовність на небі, десь на півгодини.","І я бачив сім ангелів, які стояли перед Богом, і дано їм сім труб.","І прийшов інший ангел, і став перед жертовником, тримаючи золоту кадильницю; і дано було йому багато фіміаму, щоб він з молитвами всіх святих поклав його на золотий жертовник, що перед престолом.","І піднісся дим фіміаму з молитвами святих від руки ангела перед Богом.","І взяв ангел кадильницю, і наповнив її вогнем з жертовника, і поклав на землю: і з’явилися голоси і громи, і блискавки, і землетрус.","І сім ангелів, які мали сім труб, приготувалися трубити.","Перший ангел затрубив, і сталися град і вогонь, змішані з кров’ю, і впали на землю; і третя частина дерев згоріла, і вся трава зелена згоріла.","Другий ангел затрубив, і ніби велика гора, палаюча вогнем, упала в море; і третя частина моря стала кров’ю,","і вмерла третя частина одушевлених створінь, що живуть у морі, і третя частина суден загинула.","Третій ангел затрубив, і впала з неба велика зірка, що палала подібно до світильника, і впала на третю частину рік і на джерела вод.","Ім’я цієї зірки «полин»; і третя частина вод стала, як полин, і багато з людей померло від вод, тому що вони стали гіркі.","Четвертий ангел затрубив, і уражена була третя частина сонця і третя частина місяця, і третя частина зірок, так що затьмарилася третя частина їх, і третя частина дня не була світла — так само, як і ночі.","І бачив я і чув одного ангела, який літав посеред неба і говорив гучним голосом: горе, горе, горе тим, що живуть на землі, від останніх трубних голосів трьох ангелів, які будуть трубити."],"x":{"2":"18.12.15|50.18.10","3":"76.5.8|76.6.9","4":"25.140.2","5":"76.11.19|76.16.18"}},{"v":["П’ятий ангел затрубив, і я побачив зірку, що впала з неба на землю, і дано було їй ключ від колодязя безодні.","Вона відкрила колодязь безодні, і вийшов дим з колодязя, як дим з великої печі; і затьмарилося сонце й повітря від диму з колодязя.","І з диму вийшла сарана на землю, і дано було їй силу, яку мають земні скорпіони.","І сказано було їй, щоб не робила шкоди траві земній й ніякій зелені, і ніякому дереву, а тільки одним людям, які не мають печаті Божої на чолах своїх.","І дано їй не вбивати їх, а тільки мучити п’ять місяців; і муки від неї подібні до мук від скорпіона, коли ужалить людину.","У ті дні люди будуть шукати смерти, але не знайдуть її; захочуть умерти, але смерть утече від них.","За виглядом своїм сарана була подібна до коней, приготованих на війну; і на головах у неї ніби вінці, схожі на золоті, обличчя ж її, як обличчя людські;","і волосся в неї — ніби волосся в жінок, а зуби в неї були, як у левів.","На ній були броні, ніби броні залізні, а шум від крил її, як стукіт від колісниць, коли безліч коней біжать на війну;","у неї були хвости, як у скорпіонів, і у хвостах її були жала; влада ж її була — шкодити людям п’ять місяців.","Царем над собою вона мала ангела безодні; ім’я йому по-єврейськи Аваддон, а по-грецьки Аполліон*.","Одне горе пройшло; і ось, ідуть за ним ще два горя.","Шостий ангел затрубив, і я почув один голос від чотирьох рогів золотого жертовника, який стояв перед Богом","і говорив шостому ангелу, що мав трубу: звільни чотирьох ангелів, зв’язаних біля великої річки Євфрата.","І звільнені були чотири ангели, приготовані на час і день, і місяць і рік для того, щоб умертвити третю частину людей.","Кількість кінного війська була дві тьми тем; і я чув кількість його.","Так бачив я у видінні коней і на них вершників, які мали на собі броні вогненні, гіацинтові й сірчані; голови у коней, як голови у левів, і з рота їх виходив вогонь, дим і сірка.","Від цих трьох покарань, від вогню, диму і сірки, що виходили з рота їх, померла третя частина людей;","бо сила коней була в роті їх і у хвостах їх; а хвости їх були подібні до змій і мали голови, і ними вони шкодили.","Інші ж люди, які не вмерли від цих покарань, не розкаялись у ділах рук своїх так, щоб не поклонятися бісам та золотим, срібним, мідним, кам’яним і дерев’яним ідолам, які не можуть ні бачити, ні чути, ні ходити.","І не розкаялися вони у вбивствах своїх, ні в чародійствах своїх, ні у розпусті своїй, ні в крадіжках своїх."],"x":{"4":"1.12.23|36.9.4|76.7.3","6":"24.3.21|31.2.19|38.10.8|52.23.30","8":"39.1.6","9":"39.2.5"},"n":{"11":["Губитель."]}},{"v":["І бачив я іншого ангела сильного, який сходив з неба, одягнений у хмару; над головою його була райдуга, і обличчя його, як сонце, і ноги його, як стовпи вогняні,","у руці в нього була книжка розкрита. І поставив він праву ногу свою на море, а ліву на землю,","і викликнув гучним голосом, як рикає лев; і коли він викликнув, тоді сім громів проговорили голосами своїми.","І коли сім громів проговорили голосами своїми, я хотів було писати; але почув голос з неба, що говорив мені: приховай, що говорили сім громів, і не пиши цього.","І ангел, що стоїть на морі і на землі, якого я бачив, підняв руку свою до неба","і клявся Тим, Хто живе у віки віків, Який створив небо і все, що на ньому, землю і все, що на ній, і море і все, що у ньому, що часу вже не буде;","але в ті дні, коли проголосить сьомий ангел, коли він затрубить, звершиться тайна Божа, як Він благовістив рабам Своїм пророкам.","І голос, який я чув з неба, знову став говорити зі мною і сказав: піди, візьми розкриту книжку з руки ангела, який стоїть на морі і на землі.","І я пішов до ангела і сказав йому: дай мені книжку. Він сказав мені: візьми і з’їж її; вона буде гірка у череві твоїм, але в устах твоїх буде солодка, як мед.","І взяв я книжку з руки ангела, і з’їв її; і вона в устах моїх була солодкою, як мед; коли ж з’їв її, то гірко стало у череві моєму.","І сказав він мені: тобі належить знову пророкувати про народи і племена, і людей і царів багатьох."],"x":{"1":"36.1.27|50.17.2|76.1.15","4":"37.12.4:9","5":"37.12.7","6":"17.9.6","7":"76.11.15","9":"36.2.8|36.3.1:3"}},{"v":["І дано мені тростину, подібну до жезла, і сказано: встань і виміряй храм Божий і жертовник, і тих, що поклоняються в ньому.","А зовнішній двір храму виключи і не вимірюй його, бо він відданий язичникам: вони зневажатимуть святе місто сорок два місяці.","І дам двом свідкам Моїм, і вони будуть пророкувати тисячу двісті шістдесят днів, одягнені у веретище.","Це два оливкових дерева і два світильники, що стоять перед Богом землі.","І якщо хто захоче їх образити, то вогонь вийде з уст їхніх і пожере ворогів їхніх; якщо хто захоче скривдити їх, тому належить бути вбитому.","Вони мають владу зачинити небо, щоб не йшов дощ на землю в дні пророкування їхнього; і мають владу над водами, перетворювати їх на кров, і вражати землю всякими недугами, коли тільки схочуть.","І коли вони закінчать свідчення своє, звір, що виходить з безодні, битиметься з ними, і переможе їх, і вб’є їх,","і трупи їхні залишить на вулиці великого міста, яке духовно зветься Содом і Єгипет, де і Господь наш був розіп’ятий.","І багато з народів і колін, і людей, і племен дивитимуться на трупи їхні три дні з половиною, і не дозволять покласти трупи їхні у гроби.","І ті, що живуть на землі, будуть радіти цьому і веселитися, і пошлють дари одне одному, тому що два ці пророки мучили тих, що живуть на землі.","Але після трьох з половиною днів увійшов у них дух життя від Бога, і вони обоє стали на ноги свої; і великий страх напав на тих, які дивилися на них.","І почули вони з неба гучний голос, що говорив їм: зійдіть сюди. І вони зійшли на небо на хмарі; і дивилися на них вороги їхні.","І в ту ж мить стався великий землетрус, і десята частина міста впала, і загинуло під час землетрусу сім тисяч імен людських; інші ж охоплені були страхом і воздали славу Богові Небесному.","Друге горе минуло; ось, гряде скоро третє горе.","І сьомий ангел затрубив, і залунали на небі гучні голоси, які промовляли: царство світу стало царством Господа нашого і Христа Його, і буде царювати повік.","І двадцять чотири старці, які сидять перед Богом на престолах своїх, впали на лиця свої і поклонилися Богові,","говорячи, дякуємо Тобі, Господи Боже, Вседержителю, Який є, і був, і грядеш, що Ти прийняв силу Твою велику і воцарився.","І розлютилися язичники; і прийшов гнів Твій, і час судити мертвих і дати відплату рабам Твоїм, пророкам і святим, і тим, що бояться імені Твого, малим і великим, і погубити тих, які губили землю.","І розкрився храм Божий на небі, і з’явився ковчег завіту Його в храмі Його; і сталися блискавки і голоси, і громи, і землетрус, і великий град."],"x":{"1":"76.21.15","2":"76.13.5","4":"48.4.3|48.11.14","5":"31.11.4|32.5.14|38.6.5|70.2.8","6":"1.7.19|10.17.1","7":"76.17.8","14":"76.8.13|76.9.12","15":"76.10.7","16":"76.4.4"}},{"v":["І з’явилося на небі велике знамення: жона, оповита сонцем; під ногами її місяць і на голові її вінець з дванадцяти зірок.","Вона мала в утробі і кричала від болю і мук народження.","І з’явилось інше знамення на небі: ось, дракон величезний червоний з сімома головами і десятьма рогами, і на головах його сім вінців.","Хвіст його захопив з неба третю частину зірок і кинув їх на землю. Дракон цей став перед жоною, яка мала родити, щоб, коли вона народить, пожерти її немовля.","І народила вона немовля чоловічої статі, якому належить пасти всі народи залізним жезлом; і піднесене було дитя її до Бога і престолу Його.","А жона втекла в пустелю, де було приготоване їй місце від Бога, щоб там годували її тисячу двісті шістдесят днів.","І відбулася на небі війна: Михаїл і ангели його воювали проти дракона, і дракон і ангели його воювали проти них,","та не встояли, і не знайшлося вже місця для них на небі.","І скинутий був великий дракон, древній змій, званий дияволом і сатаною, що спокушає всю вселенну, скинутий на землю, і ангели його скинуті з ним.","І почув я гучний голос на небі, який промовляв: нині настало спасіння, і сила, і царство Бога нашого і влада Христа Його, тому що скинутий наклепник братів наших, який зводив наклепи на них перед Богом нашим день і ніч.","Вони перемогли його кров’ю Агнця і словом свідчення свого і не полюбили душі своєї* навіть до смерти.","Отже, веселіться, небеса і ті, що живуть на них! Горе тим, що живуть на землі і на морі! Бо зійшов диявол до вас у великій люті, знаючи, що небагато йому лишається часу.","Коли ж дракон побачив, що скинутий на землю, то став переслідувати жону, яка народила дитя чоловічої статі.","І були дані жоні два крила великого орла, щоб вона летіла в пустелю на місце своє від лиця змія і там годувалася протягом часу, часів і півчасу.","І пустив змій услід за жоною з пащі своєї воду, мов річку, щоб потопити її в річці.","Але земля допомогла жоні, і розкрила земля уста свої, і поглинула річку, яку дракон пустив з пащі своєї.","І розлютився дракон на жону, і пішов, щоб вступити в бій з іншими з роду її, які зберігають заповіді Божі і мають свідчення Ісуса Христа."],"x":{"3":"76.13.1|76.17.3|76.20.2","5":"25.2.9|63.15.25|76.2.27","6":"76.11.3","7":"37.10.13|37.12.1","9":"52.10.18","10":"48.3.1","11":"62.8.37","12":"31.49.13"},"n":{"11":["Життя свого."]}},{"v":["І став я на піску морському, і побачив звіра з сімома головами і десятьма рогами, що виходив з моря: на рогах його було десять вінців, а на головах його богохульні імена.","Звір, якого я бачив, був подібний до барса; ноги в нього — як у ведмедя, а паща в нього — як паща у лева; і дав йому дракон силу свою і престіл свій, і велику владу.","І бачив я, що одна з голів його ніби була смертельно поранена; але ця смертельна рана зцілилась. І дивувалась уся земля, слідкуючи за звіром, і поклонилися драконові, що дав владу звірові,","і поклонилися звірові, кажучи: хто подібний до звіра цього? і хто може змагатися з ним?","І дані були йому вуста, що говорять гордо і богохульно, і надана йому влада діяти сорок два місяці.","І розкрив він уста свої для хули на Бога, щоб хулити ім’я Його й оселю Його, і тих, що живуть на небі.","І дано було йому вести війну зі святими і перемогти їх; і дана була йому влада над усяким коліном і народом, і людьми, і племенем.","І поклоняться йому всі, що живуть на землі, імена яких не написані в книзі життя у Агнця, заколеного від створіння світу.","Хто має вухо, нехай чує.","Хто веде в полон, той сам піде у полон; хто мечем убиває, тому самому належить бути вбитому мечем. Ось тут терпіння і віра святих.","І побачив я іншого звіра, що виходив із землі; він мав два роги, подібні до ягнячих, і говорив, як дракон.","Він діє перед ним з усією владою першого звіра і примушує всю землю і тих, що живуть на ній, поклонятися першому звірові, у якого смертельна рана зцілилась;","і творить великі знамення, так що й вогонь зводить з неба на землю перед людьми.","І чудесами, які дано було йому творити перед звіром, він спокушає, тих, що живуть на землі, кажучи тим, що живуть на землі, щоб вони зробили образ звіра, який має рану від меча і живий.","І дано було йому вкласти дух в образ звіра, щоб образ звіра і говорив і діяв так, щоб убитий був кожен, хто не поклониться образу звіра.","І він зробить те, що всім, малим і великим, багатим і вбогим, вільним і рабам буде начертання на праву руку їх або на чоло їх,","і що нікому не можна буде ні купувати, ні продавати, крім того, хто має це начертання, або ім’я звіра, або число імені його.","Тут мудрість. Хто має розум, той нехай полічить число звіра, бо це число людське; число його шістсот шістдесят шість."],"x":{"1":"37.7.7|76.12.3|76.17.3","5":"37.7.8|37.11.36","7":"37.7.21|76.11.7","8":"37.12.1|67.4.3|76.17.8|76.21.27","10":"0.9.6|31.33.1|50.26.52|76.14.12","13":"4.13.2|50.24.24|76.16.14","16":"76.14.11","18":"76.17.9"}},{"v":["І глянув я, і ось, Агнець стоїть на горі Сионі, і з ним сто сорок чотири тисячі, в яких ім’я Отця Його написане на чолах.","І почув я голос з неба, наче шум багатьох вод і наче гуркіт грому сильного; і почув голос ніби гуслярів, які грають на гуслах своїх.","Вони співають ніби нову пісню перед престолом і перед чотирма тваринами і старцями; і ніхто не міг навчитися цієї пісні, крім цих ста сорока чотирьох тисяч, відкуплених від землі.","Це ті, які не осквернилися з жінками, бо вони дівственики; це ті, які йдуть услід за Агнцем, куди б Він не пішов. Вони відкуплені з людей, як первістки Богові і Агнцеві,","і в устах їхніх нема лукавства; вони непорочні перед престолом Божим.","І побачив я іншого ангела, що летів посеред неба, який мав вічне Євангеліє, щоб благовістити тим, які живуть на землі, усякому племені, і коліну, і людям, й народу;","і говорив він гучним голосом: бійтеся Бога і воздайте Йому славу, бо настав час суду Його, і поклоніться Тому, Хто створив небо і землю, і море, і джерела вод.","І другий ангел ішов за ним слідом, кажучи: впав, упав Вавилон, місто велике, тому що він шаленим вином розпусти своєї напоїв усі народи.","І третій ангел ішов за ними слідом, кажучи гучним голосом: хто поклоняється звірові і образу його і приймає начертання на чоло своє або на руку свою,","той питиме вино гніву Божого, вино нерозведене, приготовлене в чаші гніву Його, і буде мучений у вогні і сірці перед святими ангелами і перед Агнцем;","і дим мучення їх здійматиметься повік, і не матимуть спокою ні вдень, ні вночі ті, що поклоняються звірові і образу його, і ті, що приймають начертання імені його.","Тут терпіння святих, які дотримуються заповідей Божих і віри в Ісуса.","І почув я голос з неба, який говорив мені: напиши: віднині блаженні мертві, які вмирають у Господі; так, говорить Дух, вони заспокояться від трудів своїх, і діла їхні йдуть услід за ними.","І поглянув я, і ось світла хмара, і на хмарі сидить подібний до Сина Людського; на голові Його золотий вінець, і в руці Його гострий серп.","І вийшов інший ангел з храму і викликнув гучним голосом до Того, Хто сидить на хмарі: пусти серп Твій і пожни, бо настав час жати, тому що жниво на землі вже дозріло.","І кинув Той, Хто сидить на хмарі, серп свій на землю, і земля була пожата.","І інший ангел вийшов з храму, що знаходиться на небі, також з гострим серпом.","І інший ангел, який має владу над вогнем, вийшов від жертовника і з великим криком викликнув до того, що має гострий серп, кажучи: пусти серп твій гострий і обріж грона винограду на землі, бо дозріли вже на ньому ягоди.","І кинув ангел серп свій на землю, й обрізав виноград на землі, і кинув у велике точило гніву Божого.","І потоптано ягоди у точилі за містом, і потекла кров з точила навіть до вуздечок кінських, на тисячу шістсот стадій."],"x":{"1":"36.9.4|76.7.3","2":"76.5.8|76.19.6","4":"63.6.20|64.7.1","5":"46.3.13|66.5.27","7":"25.32.6|25.145.6|54.14.15","8":"31.21.9|32.51.8-9|36.16.35|76.16.19","10":"25.74.9|31.66.24|32.25.9|76.16.19","11":"3.34.10|50.25.41|53.5.29|76.19.3","13":"29.4.7|69.4.14","14":"37.7.13","15":"39.3.13|50.13.39","18":"76.8.5","19":"76.19.15","20":"31.63.3"}},{"v":["І побачив я інше знамення на небі, велике і дивне: сім ангелів, які мали сім останніх покарань, якими закінчувався гнів Божий.","І бачив я ніби скляне море, змішане з вогнем; і переможці звіра та образу його, начертання його і числа імені його, стоять на цьому скляному морі, тримаючи гусла Божі,","і співають пісню Мойсея, раба Божого, і пісню Агнця, говорячи: великі й дивні діла Твої, Господи Боже Вседержителю! Праведні та істинні путі Твої, Царю святих!","Хто не убоїться Тебе, Господи, і не прославить імені Твого? Бо Ти єдиний святий. Усі народи прийдуть і поклоняться перед Тобою, бо відкрилися суди Твої.","І після цього я глянув, і ось, розкрився храм скинії свідчення на небі.","І вийшли з храму сім ангелів, які мали сім покарань, одягнені в чисту і світлу лляну одежу і підперезані попід груди золотими поясами.","І одна з чотирьох тварин дала сімом ангелам сім золотих чаш, наповнених гнівом Бога, Який живе у віки віків.","І наповнився храм димом від слави Божої і від сили Його, і ніхто не міг увійти до храму, доки не скінчилися сім покарань семи ангелів."],"x":{"2":"76.4.6","3":"1.15.1|1.6.13|4.32.4|25.144.17|38.14.10","4":"32.10.7","8":"31.6.4"}},{"v":["І почув я з храму гучний голос, що говорив до семи ангелів: ідіть і вилийте сім чаш гніву Божого на землю.","Пішов перший ангел і вилив чашу свою на землю: і зробилися тяжкі й огидні гнійні рани на людях, які мали начертання звіра і поклонялися образу його.","Другий ангел вилив чашу свою в море: і зробилася кров, ніби мерця, і все одушевлене померло в морі.","Третій ангел вилив чашу свою у річки і джерела вод: і зробилася кров.","І почув я ангела вод, який говорив: праведний Ти, Господи, Який є і був, і святий, тому що так судив;","за те, що вони пролили кров святих і пророків, Ти дав їм пити кров: вони достойні того.","І почув я іншого, який говорив від жертовника: так, Господи Боже Вседержителю, істинні і праведні суди Твої.","Четвертий ангел вилив чашу свою на сонце: і дано було йому палити людей вогнем.","І палила людей сильна спека, і вони хулили ім’я Бога, Який має владу над цими покараннями, і не напоумилися, щоб віддати Йому славу.","П’ятий ангел вилив чашу свою на престіл звіра: і зробилося царство його темне, і вони кусали язики свої від страждання,","і хулили Бога небесного за страждання свої і за кари на них; і не розкаялись у ділах своїх.","Шостий ангел вилив чашу свою у велику ріку Євфрат: і висохла в ній вода, щоб готовий був шлях царям від сходу сонячного.","І бачив я, що виходять з уст дракона, і з уст звіра, і з уст лжепророка три духи нечисті, подібні до жаб:","це — бісівські духи, що творять знамення; вони виходять до царів землі усієї вселенної, щоб зібрати їх на битву в оний великий день Бога Вседержителя.","Ось, іду, як злодій: блаженний, хто пильнує і береже одежу свою, щоб не ходити йому нагим і щоб не побачили сорому його.","І він зібрав їх на місце, яке по-єврейськи зветься Армагеддон.","Сьомий ангел вилив чашу свою на повітря: і з храму небесного від престолу пролунав гучний голос, який сказав: звершилось!","І з’явилися блискавки, громи і голоси, і стався великий землетрус, якого не бувало з тієї пори, як люди на землі. Такий землетрус! Такий великий!","І місто велике розпалося на три частини, і міста язичницькі впали, і Вавилон великий згаданий перед Богом, щоб дати йому чашу вина лютости гніву Його.","І всякий острів зник, і гір не стало;","і град, завбільшки як талант, упав з неба на людей; і хулили люди Бога за покарання градом, тому що покарання від нього було дуже тяжке."],"x":{"2":"1.9.9|76.13.17","5":"76.4.8","6":"31.49.26|50.23.34","12":"32.50.38","13":"76.12.9|76.19.20|76.20.10","14":"50.24.24","15":"50.24.46|52.12.39|64.5.3|69.5.2|76.3.3","18":"76.4.5|76.8.5|76.11.13","19":"32.25.15|76.14.8"}},{"v":["І прийшов один з семи ангелів, які мали сім чаш, і, говорячи зі мною, сказав мені: підійди, я покажу тобі суд над великою блудницею, яка сидить на водах многих;","з нею блудодіяли царі земні, і вином її блудодіяння впивалися ті, що живуть на землі.","І повів мене в дусі в пустелю; і я побачив жінку, яка сиділа на звірі багряному, сповненому імен богохульних, з сімома головами і десятьма рогами.","І жінка була одягнена в порфиру і багряницю, прикрашена золотом, коштовними каменями і перлами, і тримала золоту чашу в руці своїй, наповнену мерзотами і нечистотою блудодійства її;","і на чолі її написано ім’я: таїна, Вавилон великий, мати блудницям і мерзотам земним.","Я бачив, що жінка упоєна була кров’ю святих і кров’ю свідків Ісусових, і, бачачи її, дивувався здивуванням великим.","І сказав мені ангел: що ти дивуєшся? Я скажу тобі таємницю жінки цієї і звіра, який носить її та має сім голів і десять рогів.","Звір, якого ти бачив, був, і нема його, і вийде з безодні, і піде у погибель; і здивуються ті з живих на землі, імена яких не вписані до книги життя від початку світу, коли побачать, що звір був, і нема його, і з’явиться.","Тут розум, що має мудрість. Сім голів — це сім гір, на яких сидить жінка,","і сім царів, з яких п’ять упали, один є, а інший ще не прийшов, і коли прийде, не довго йому бути.","І звір, який був і якого нема, є восьмий, і з числа семи, і піде у погибель.","І десять рогів, що ти бачив, є десять царів, які ще не одержали царства, але приймуть владу зі звіром, як царі, на одну годину.","Вони мають одні думки і передадуть силу і владу свою звірові.","Вони будуть вести битву з Агнцем, і Агнець переможе їх; бо Він є Господь над владиками і Цар царів, і ті, які з Ним, є покликані й обрані і вірні.","І говорить мені: води, що ти бачив, де сидить блудниця, це люди й народи, і племена і коліна.","І десять рогів, які ти бачив на звірі, ці зненавидять блудницю, і розорять її, і роздягнуть, і плоть її з’їдять, і спалять її у вогні;","тому що Бог поклав їм на серце — виконати волю Його, виконати одну волю, і віддати царство їхнє звірові, доки не здійсняться слова Божі.","Жінка ж, яку ти бачив, є велике місто, що царює над земними царями."],"x":{"1":"44.3.4","2":"32.51.7|76.14.8|76.18.3","3":"76.13.1","5":"76.16.19|76.18.2","8":"37.12.1|76.11.7|76.13.1|76.20.12","12":"37.7.20|76.13.1","14":"37.7.27|50.28.18|71.6.15|76.18.8|76.19.16","15":"31.8.7","16":"76.18.8","18":"76.16.19"}},{"v":["Після цього я побачив іншого ангела, який сходив з неба і мав владу велику; і земля освітилася від слави його.","І вигукнув він сильно, гучним голосом, кажучи: упав, упав Вавилон, велика блудниця; він зробився житлом бісів і пристановищем усякому нечистому духові, пристановищем усякому нечистому й огидному птахові; бо лютим вином блудодіяння свого вона напоїла всі народи,","і царі земні любодіяли з нею, і купці земні розбагатіли від великих розкошів її.","І почув я інший голос з неба, який говорив; вийди від неї, народе Мій, щоб не брати вам участі у гріхах її та не зазнати покарань її;","бо гріхи її дійшли до неба, і Бог пригадав неправди її.","Відплатіть їй так, як і вона відплатила вам, і удвічі відплатіть їй за ділами її; у чаші, в якій вона готувала вам вино, приготуйте їй удвічі.","Скільки славилася вона і розкошувала, стільки завдайте їй мук і скорбот. Бо вона говорить у серці своєму: сиджу царицею, я не вдова і не побачу скорботи!","За те в один день прийдуть на неї страти, смерть і плач, і голод, і буде спалена вогнем, тому що сильний Господь Бог, Який судить її.","І заплачуть і заридають за нею царі земні, які блудодіяли і розкошували з нею, коли побачать дим від пожежі її,","стоячи віддалік від страху мук її та кажучи: горе, горе тобі, велике місто Вавилон, місто могутнє! Бо за одну годину прийшов суд твій.","І купці земні заплачуть і заридають за нею, тому що товарів їхніх ніхто вже не купує,","товарів золотих і срібних, і каменів коштовних та перлів, і висону і порфири, і шовку, і багряниці, і всякого пахучого дерева, і всяких виробів із слонової кістки, і всяких виробів з дорогих дерев, з міді і заліза, і мармуру,","кориці і фіміаму, і мира і ладану, і вина і єлею, і борошна і пшениці, і худоби і овець, і коней і колісниць, і тіл і душ людських.","І плодів, угодних для душі твоєї, не стало у тебе, і все сите і блискуче віддалилося від тебе; ти вже не знайдеш його.","Торговці всім цим, які збагатилися від неї, стануть вдалині від страху мук її, плачучи і ридаючи,","і кажучи: горе, горе тобі, велике місто, одягнене у висон і порфиру і багряницю, прикрашене золотом і камінням коштовним і перлами,","бо за одну годину загинуло таке багатство! І всі керманичі, і всі, хто пливе на кораблях, і всі корабельники, і всі, хто торгує на морі, стали віддаля,","і, бачачи дим від пожежі її, закричали, кажучи: яке місто подібне до міста великого!","І посипали попелом голови свої, і кричали, плачучи і ридаючи: горе, горе тобі, місто велике, коштовностями якого збагатились усі, хто має кораблі на морі, бо опустіло за одну годину!","Веселися з цього, небо, і святі апостоли та пророки; бо звершив Бог суд ваш над ним.","І один сильний ангел узяв камінь, подібний до великого жорна, і кинув у море, кажучи: з такою швидкістю повержений буде Вавилон, велике місто, і вже не буде його.","І голосу тих, що грають на гуслах, і співають, і грають на сопілках, і трублять у труби, в тобі вже не буде чутно; не буде вже в тобі ніякого митця, ніякого мистецтва, і шуму від жорен вже не буде чутно в тобі;","і світло світильника вже не з’явиться в тобі; і голосів жениха і нареченої не буде вже чутно в тобі: бо купці твої були вельможами землі, і чародійством твоїм були введені в оману всі народи.","І в ньому знайдена кров пророків і святих, і всіх убитих на землі."],"x":{"1":"36.43.2","2":"31.13.19|31.21.9|32.50.1|32.51.8|35.4.35","3":"76.17.2","4":"31.48.20|31.52.11|48.2.7","5":"32.51.49","7":"46.2.15","10":"36.27.27:30|76.14.8","17":"32.50.23|32.51.13","20":"31.44.23|31.49.13|32.51.48","21":"32.51.63-64","22":"36.26.13","23":"32.7.34|76.17.2","24":"76.17.6"}},{"v":["Після цього я почув на небі гучний голос, ніби численного народу, який говорив: алилуя! спасіння і слава, і честь і сила Господу нашому!","Бо істинні і праведні суди Його: тому що Він осудив ту велику любодійницю, яка розбестила землю любодійством своїм, і відомстив за кров рабів Своїх від руки її.","І вдруге сказали: алилуя! І дим її здіймався на віки віків.","Тоді двадцять чотири старці і чотири тварини упали і поклонилися Богові, Який сидить на престолі, кажучи: амінь! алилуя!","І голос від престолу вийшов, говорячи: хваліть Бога нашого, всі раби Його і всі, що бояться Його, малі й великі.","І чув я ніби голос численного народу, ніби шум вод багатьох, ніби голос громів сильних, що говорили: алилуя! бо воцарився Господь Бог Вседержитель.","Радіймо і звеселімось, і воздаймо Йому славу; бо настав шлюб Агнця, і жона Його приготувала себе.","І дано було їй одягнутися у висон чистий і світлий, виссон же є праведність святих.","І сказав мені ангел: напиши: блаженні, покликані на шлюбну вечерю Агнця. І сказав мені: ці є істинні слова Божі.","Я впав до ніг його, щоб поклонитися йому; але він сказав мені: дивись, не роби цього; я співслужитель тобі і братам твоїм, які мають свідчення Ісусове; Богу поклонись; бо свідчення Ісусове є дух пророцтва.","І побачив я відкрите небо, і ось кінь білий, і Той, Хто сидить на ньому, називається Вірний і Істинний, Який праведно судить і воює.","Очі в Нього, як полум’я вогненне, і на голові Його багато вінців. Він мав ім’я написане, якого ніхто не знав, крім Нього Самого.","Він був одягнений в одежу, обагрену кров’ю. Ім’я Йому: «Слово Боже».","І воїнства небесні їхали слідом за Ним на конях білих, одягнені у висон, білий і чистий.","З уст же Його виходить гострий меч, щоб ним уражати народи. Він пасе їх жезлом залізним; Він топче точило вина лютости і гніву Бога Вседержителя.","На одязі і на стегні Його написано ім’я: Цар царів і Господь володарів.","І побачив я одного ангела, який стояв на сонці; і він викликнув гучним голосом, кажучи усім птахам, що літали в небі: летіть, збирайтесь на велику вечерю Божу,","щоб пожерти трупи царів, трупи сильних, трупи тисячоначальників, трупи коней і тих, що сидять на них, трупи всіх вільних і рабів, малих і великих.","І побачив я звіра і царів земних, і воїнства їх, зібраних, щоб битися з Тим, Хто сидить на коні, і з воїнством Його.","І схоплений був звір і з ним лжепророк, який творив перед ним чудеса, якими він спокусив тих, що прийняли начертання звіра, і тих, які поклоняються його зображенню: обоє живими були кинуті в озеро вогненне, що горіло сіркою;","а інші убиті мечем Того, Хто сидить на коні, який виходить з уст Його, і всі птахи наситились їхніми трупами."],"x":{"1":"4.32.43|76.7.10|76.12.10","3":"31.34.10|76.14.11","4":"76.4.4|76.5.14|76.15.3","6":"36.1.24|36.43.2|76.11.15","7":"25.44.14|26.9.1|50.22.2|52.14.16|64.11.2|76.21.2","8":"76.3.18","11":"76.7.9","12":"76.1.14|76.2.18","13":"31.63.2|53.1.1","15":"25.2.9|31.11.4|31.63.3","16":"76.17.14|76.19.12","17":"32.12.9|36.39.17","20":"76.20.10"}},{"v":["І побачив я ангела, який сходив з неба і мав ключ від безодні і великий ланцюг у руці своїй.","Він узяв дракона, змія древнього, який є диявол і сатана, і скував його на тисячу років,","і скинув його у безодню, і замкнув його, і поклав над ним печать, щоб не спокушав уже народи, доки не скінчиться тисяча років; після ж цього він має бути звільненим на короткий час.","І побачив я престоли і тих, хто сидить на них, яким дано було судити, і душі обезглавлених за свідчення Ісуса і за слово Боже, які не поклонились звірові, ні образу його, і не прийняли начертання на чоло своє і на руку свою. Вони ожили і царювали з Христом тисячу років.","Інші ж з померлих не ожили, доки не скінчиться тисяча років. Це — перше воскресіння.","Блаженний і святий, хто має участь у воскресінні першому: над ним смерть друга не має влади, але вони будуть священиками Бога і Христа і будуть царювати з Ним тисячу років.","Коли ж скінчиться тисяча років, сатана буде звільнений з темниці своєї і вийде спокушати народи, які знаходяться на чотирьох кутах землі, Гога і Магога, і збирати їх на битву; число їх як пісок морський.","І вийшли на широту землі, й оточили стан святих і місто улюблене.","І впав вогонь з неба від Бога і пожер їх;","а диявол, що спокушав їх, ввергнутий в озеро вогненне і сірчане, де звір і лжепророк, і будуть мучитися день і ніч на віки віків.","І побачив я великий білий престіл і Того, хто сидить на ньому, від лиця Якого втікали небо і земля, і не знайшлось їм місця.","І побачив я мертвих, малих і великих, що стояли перед Богом, і книги розкриті були, й інша книга розкрита, яка є книга життя; і судимі були мертві за написаним у книгах, згідно з ділами своїми.","Тоді віддало море мертвих, що були в ньому, і смерть і пекло віддали мертвих, які були в них; і судимий був кожен за ділами своїми.","І смерть і пекло ввергнуті в озеро вогненне. Це смерть друга.","І хто не був записаний у книзі життя, той був кинутий в озеро вогненне."],"x":{"1":"52.8.31|76.1.18","2":"57.2.4|61.1.6|76.12.9","4":"37.7.9:22|37.8.17|50.19.28|63.6.2|72.2.12|76.6.11","6":"31.61.6|76.1.6|76.21.7","7":"36.38.2|36.39.1|76.16.14","9":"31.66.24|76.14.10","10":"37.7.11|76.19.20","11":"57.3.10","12":"76.2.23|76.3.5|76.13.8|76.21.27","14":"63.15.26|76.2.11"}},{"v":["І побачив я нове небо і нову землю, бо перше небо і перша земля минули, і моря вже нема.","І я, Іоан, побачив святе місто Єрусалим, новий, що сходив від Бога з неба, приготований, як наречена, прикрашена для чоловіка свого.","І почув я гучний голос з неба, який говорив: ось, скинія Бога з людьми, і Він буде жити з ними; вони будуть Його народом, і Сам Бог з ними буде Богом їхнім.","І витре Бог усяку сльозу з очей їхніх, і смерти не буде вже, ні плачу, ні крику, ні недуги вже не буде, бо колишнє минуло.","І сказав Той, Хто сидить на престолі: ось, творю все нове. І каже мені: напиши; бо слова ці істинні й вірні.","І сказав мені: звершилось! Я є Альфа й Омега, початок і кінець; спраглому дам задарма від джерела води живої.","Переможець успадкує все, і буду йому Богом, і він буде Мені сином.","Боязких же і невірних, мерзотних і убивць і любодіїв, і чародіїв та ідолослужителів, і всіх неправдомовців — доля в озері, що горить вогнем і сіркою. Це смерть друга.","І прийшов до мене один з семи ангелів, у яких було сім чаш, наповнених сімома останніми покараннями, і сказав мені: піди, я покажу тобі жону, наречену Агнця.","І возніс мене в дусі на велику й високу гору, і показав мені велике місто, святий Єрусалим, який сходив з неба від Бога.","Він має славу Божу. Світило його подібне до коштовного каменя, ніби каменя яспису кристаловидного.","Він має велику і високу стіну, має дванадцять брам і на них дванадцять ангелів; на брамах написані імена дванадцяти колін синів Ізраїлевих:","зі сходу три брами, з півночі три брами, з півдня три брами, із заходу три брами.","Стіна міста має дванадцять підвалин, і на них імена дванадцяти апостолів Агнця.","Той, що говорив зі мною, мав золоту тростину для вимірювання міста, і брам його, і стіни його.","Місто розташоване чотирикутником, і довжина його така сама, як і ширина. І виміряв він місто тростиною на дванадцять тисяч стадій; довжина і ширина і висота його рівні.","І стіну його виміряв у сто сорок чотири лікті, мірою людською, яка міра й ангела.","Стіна його побудована з яспису, а місто було — чисте золото, подібне до чистого скла.","Підвалини стіни міста прикрашені всяким коштовним камінням: підвалина перша яспис, друга сапфір, третя халкидон, четверта смарагд,","п’ята сардонікс, шоста сердолік, сьома хризоліт, восьма берил, дев’ята топаз, десята хризопраз, одинадцята гіацинт, дванадцята аметист.","А дванадцять брам — дванадцять перлин: кожна брама була з однієї перлини. Вулиця міста — чисте золото, як прозоре скло.","Храму ж я не бачив у ньому, бо Господь Бог Вседержитель — храм його, і Агнець.","І місто не має потреби ні в сонці, ні у місяці для освітлення свого, бо слава Божа освітила його, і світильник його — Агнець.","Спасенні народи будуть ходити у світлі його, і царі земні принесуть до нього славу і честь свою.","Брами його не будуть зачинятися вдень; а ночі там не буде.","І принесуть до нього славу і честь народів.","І не ввійде до нього ніщо нечисте, і ніхто, підданий мерзоті і неправді, а тільки ті, які написані у Агнця в книзі життя."],"x":{"1":"31.65.17|57.3.13","2":"31.52.1|31.54.5|64.11.2|65.4.26|75.12.22|76.3.12","3":"2.26.12|36.43.7","4":"31.25.8|31.35.10|76.7.17","5":"31.43.19|64.5.17","6":"76.1.8:10|76.22.13","7":"75.8.10","8":"63.6.9|65.5.19-21","9":"76.15.1|76.19.7","12":"36.48.31","14":"50.16.18|65.2.9|66.2.20","15":"36.40.3","19":"1.28.17|31.54.11","23":"31.60.19|76.22.5","24":"31.60.3:5","25":"31.60.11:20|76.22.5","27":"31.35.8|76.20.12"}},{"v":["І показав мені чисту ріку води життя, світлу, як кристал, що виходила від престолу Бога і Агнця.","Серед вулиці його, і по той і по інший бік річки, — дерево життя, яке дванадцять разів приносить плоди, дає на кожен місяць плід свій; і листя дерева — для зцілення народів.","І нічого вже не буде проклятого; але престіл Бога і Агнця буде в ньому, і раби Його будуть служити Йому.","І побачать лице Його, й ім’я Його буде на чолах їхніх.","І ночі не буде там, і не будуть мати потреби ні у світильнику, ні у світлі сонячному, бо Господь Бог освітлює їх; і будуть царювати на віки віків.","І сказав мені: ці слова вірні й істинні; і Господь, Бог святих пророків, послав ангела Свого показати рабам Своїм те, чому належить бути невдовзі.","Ось, прийду скоро: блаженний, хто додержує слова пророцтва книги цієї.","Я, Іоан, бачив і чув це. Коли ж почув і побачив, упав до ніг ангела, який показував мені це, щоб поклонитися йому;","але він сказав мені: дивись, не роби цього; бо я співслужитель тобі і братам твоїм пророкам і тим, хто додержує слів книги цієї; Богу поклонись.","І сказав мені: не запечатуй слів пророцтва книги цієї; бо час близько.","Неправедний нехай ще чинить неправду; нечистий нехай ще оскверняється; праведний же нехай ще творить правду, і святий нехай ще освячується.","Ось, прийду скоро, відомщення Моє зі Мною, щоб воздати кожному за ділами його.","Я є Альфа й Омега, початок і кінець, Перший і Останній.","Блаженні ті, які дотримуються заповідей Його, щоб мати їм право на дерево життя і ввійти в місто воротами.","А зовні — пси і чародії, і любодії, і убивці, й ідолослужителі, і всякий, хто любить і чинить неправду.","Я, Ісус, послав Ангела Мого засвідчити вам це у церквах. Я є корінь і нащадок Давидів, зірка світла і ранкова.","І Дух і наречена говорять: прийди! І той, хто чув, нехай скаже: прийди! Хто спраглий, нехай приходить, і хто бажає, нехай бере воду життя задарма.","І я також свідчу всякому, хто чує слова пророцтва книги цієї: коли хто додасть щось до них, на того накладе Бог покарання, про які написано в книзі цій;","і коли хто відійме щось від слів книги пророцтва цього, в того відійме Бог участь у книзі життя й у святому місті, і в тому, що написано в книзі цій.","Хто свідчить це, говорить: так, гряду скоро! Амінь. Так, гряди, Господи Ісусе!","Благодать Господа нашого Ісуса Христа з усіма вами. Амінь."],"x":{"1":"36.47.1|48.14.8|76.4.6","2":"36.47.12|76.2.7","4":"50.5.8|58.3.2|63.13.12","5":"31.60.19|76.21.23","6":"76.1.1|76.19.9|76.21.5","7":"76.1.3|76.3.11","9":"76.19.10","10":"76.1.3","11":"36.3.27|37.12.10|72.3.13","12":"76.20.12","13":"76.1.8","14":"76.2.7","15":"66.5.5|67.3.2|76.21.8","16":"3.24.17|57.1.19|62.15.12|76.2.28","17":"31.55.1|53.7.37|76.21.6","18":"4.4.2|4.12.32|26.30.6"}}];
export default C;
